mapper.select:
SELECT b.*
FROM mes_building_team_user_link a
INNER JOIN mes_building_team b ON a.team_id = b.id
a.user_id = #{userId}
    
        AND b.production_line_id = #{productionLineId}
    
    AND b.process_id = #{processId}
    AND b.bool_delete_enum = FALSE
    AND a.bool_delete_enum = FALSE
    
        AND a.team_id IN
        
            #{id}

select
distinct
a.*
from mes_building_team a
left join mes_building_process pro on a.process_id = pro.id

    left join mes_building_production_line_team_link  b on a.id=b.team_id and b.bool_delete_enum=0


    
        
            Inner Join mes_building_team_user_link link on link.team_id = a.id and link.bool_delete_enum =0
            and link.user_name = #{teamUserName}
        
        
            Inner Join mes_building_team_user_link link on link.team_id = a.id and link.bool_delete_enum =0
            and link.user_name like CONCAT('%',#{teamUserName},'%')
        
    


    a.bool_delete_enum=0
    and pro.bool_delete_enum = 0
    
        AND a.id=#{id}
    
    
        AND a.workshop_id=#{workshopId}
    
    
        AND a.process_id=#{processId}
    
    
        AND a.factory_id=#{factoryId}
    
    
        AND a.workshop_id=#{workshopId}
    
    
        AND a.organization_type=#{organizationType}
    
    
        AND a.team_status=#{teamStatus}
    
    
        AND a.bool_extra_count_enum=#{boolExtraCountEnum}
    
    
        AND a.production_line_type_enum=#{productionLineTypeEnum}
    
    
        AND a.wage_quota_type=#{wageQuotaType}
    
    
        and pro.product_type = #{taskTypeEnum}
    
    
        AND a.production_line_id = #{productionLineId}
    
    
        and b.production_line_id in
        
            productionLineId
        
    
    
        and a.mes_product_enum = #{mesProductEnum}
    
    
        and pro.name in (#{i})

select team.workshop_id, team.process_id, pro.name processName, pro.type, pro.product_type as taskTypeEnum, line.id lineId, line.name lineName, team.id teamId, tuLink.user_name leaderName from mes_building_team team left join mes_building_process pro on team.process_id = pro.id left join mes_building_production_line line on team.production_line_id = line.id and line.bool_delete_enum = 0 left join mes_building_team_user_link tuLink on team.id =tuLink.team_id and tuLink.bool_leader_enum = 1 where team.bool_delete_enum = 0 and pro.bool_delete_enum = 0 and tuLink.bool_delete_enum = 0 and team.team_status = 1
and team.workshop_id = #{workShopId}
and team.production_line_id = #{productionLineId}

select team.* from (
                       select team_id from mes_building_production_line_team_link telink
                       where telink.bool_delete_enum = 0 and telink.production_line_id = #{prodLineId}
                   ) a
                       left join mes_building_team team on a.team_id = team.id
where team.bool_delete_enum = 0

select team.workshop_id, team.process_id, pro.name, pro.type, pro.product_type as taskTypeEnum, line.id lineId, line.name lineName, team.id teamId, tuLink.user_name from mes_building_team team left join mes_building_process pro on team.process_id = pro.id left join mes_building_production_line line on team.production_line_id = line.id and line.bool_delete_enum = 0 left join mes_building_team_user_link tuLink on team.id =tuLink.team_id and tuLink.bool_leader_enum = 1 where team.bool_delete_enum = 0 and pro.bool_delete_enum = 0 and tuLink.bool_delete_enum = 0 and team.team_status = 1
and team.workshop_id = #{workShopId}
and team.production_line_id = #{productionLineId}

select userLink.user_name as leaderName, team.id AS id from mes_building_team team left join mes_building_team_user_link userLink on team.id=userLink.team_id and userLink.bool_delete_enum=0 and userLink.bool_leader_enum=1 where team.bool_delete_enum = 0
and team.process_id = #{processId}
and team.workshop_id = #{workshopId}

SELECT team.*, mbtul.user_name AS name, factory.id AS 'factory.id', factory.name AS 'factory.name', workshop.id AS 'workshop.id', workshop.name AS 'workshop.name', productionLine.id AS 'productionLine.id', productionLine.name AS 'productionLine.name', process.id AS 'process.id', process.name AS 'process.name' FROM mes_building_team team LEFT JOIN mes_building_team_user_link mbtul ON mbtul.bool_delete_enum = 0 AND mbtul.bool_leader_enum = 1 AND mbtul.team_id = team.id LEFT JOIN mes_building_factory factory ON factory.bool_delete_enum = 0 AND factory.id = team.factory_id LEFT JOIN mes_building_workshop workshop ON workshop.bool_delete_enum = 0 AND workshop.id = team.workshop_id LEFT JOIN mes_building_production_line productionLine ON productionLine.bool_delete_enum = 0 AND productionLine.id = team.production_line_id LEFT JOIN mes_building_process process ON process.bool_delete_enum = 0 AND process.id = team.process_id LEFT JOIN sys_user user ON user.bool_delete_enum = 0 AND user.id = team.user_id WHERE team.bool_delete_enum = 0
AND team.id = #{id}
AND team.id IN (#{item})
AND team.process_id = #{processId}
AND mbtul.user_name LIKE CONCAT('%', #{name}, '%')
AND team.workshop_id = #{workshopId}
